#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn os_and_arch_use_the_shared_vocabulary() {
        assert_eq!(normalized_os("macos"), "MacOS");
        assert_eq!(normalized_os("linux"), "Linux");
        assert_eq!(normalized_os("windows"), "Windows");
        assert_eq!(normalized_os("ios"), "iOS");
        assert_eq!(normalized_os("netbsd"), "Other:netbsd");
        assert_eq!(normalized_os(""), "Unknown");
        assert_eq!(normalized_arch("x86_64"), "x64");
        assert_eq!(normalized_arch("aarch64"), "arm64");
        assert_eq!(normalized_arch("x86"), "x32");
        assert_eq!(normalized_arch("riscv64"), "other:riscv64");
        assert_eq!(normalized_arch(""), "unknown");
    }

    #[test]
    fn platform_headers_keep_a_caller_value() {
        let mut headers = HeaderMap::new();
        headers.insert("x-scalar-lang", HeaderValue::from_static("custom"));
        apply_platform_headers(&mut headers);
        assert_eq!(headers["x-scalar-lang"], "custom");
        assert_eq!(headers["x-scalar-runtime"], "rust");
        assert_eq!(headers["x-scalar-package-version"], env!("CARGO_PKG_VERSION"));
        assert!(!headers["x-scalar-runtime-version"].is_empty());
    }

    #[test]
    fn attempt_headers_report_the_attempt_and_whole_second_timeout() {
        let caller = HeaderMap::new();
        let mut headers = HeaderMap::new();
        AttemptHeaders::plan(&caller, Some(Duration::from_millis(90_500))).apply(&mut headers, 2);
        assert_eq!(headers["x-scalar-retry-count"], "2");
        assert_eq!(headers["x-scalar-timeout"], "90");

        let mut untimed = HeaderMap::new();
        AttemptHeaders::plan(&caller, None).apply(&mut untimed, 0);
        assert_eq!(untimed["x-scalar-retry-count"], "0");
        assert!(!untimed.contains_key("x-scalar-timeout"));

        let mut pinned = HeaderMap::new();
        pinned.insert("x-scalar-retry-count", HeaderValue::from_static("7"));
        pinned.insert("x-scalar-timeout", HeaderValue::from_static("1"));
        let mut attempt = pinned.clone();
        AttemptHeaders::plan(&pinned, Some(Duration::from_secs(30))).apply(&mut attempt, 3);
        assert_eq!(attempt["x-scalar-retry-count"], "7");
        assert_eq!(attempt["x-scalar-timeout"], "1");
    }
}
